function plan({ body, token }) {
  if (typeof token !== "string" || !token || body?.token !== token)
    throw Error("Invalid Mattermost webhook token");
  if (typeof body?.channel_id !== "string" || !body.channel_id || typeof body?.text !== "string")
    throw Error("Invalid Mattermost event");
  const match = ["guys", "Guys", "bros", "Bros", "dudes", "Dudes", "gals", "Gals"].some((word) =>
    body.text.includes(word),
  );
  return { match, channelId: body.channel_id };
}

const result = plan({ body: $json.body, token: $env.MATTERMOST_OUTGOING_TOKEN });
return result.match ? { json: result } : null;
